def solve(payload):
    values = {}
    for part in payload.get('text', '').split(';'):
        if '=' not in part:
            continue
        key, value = part.split('=', 1)
        value = value.strip()
        if value == 'true': value = True
        elif value == 'false': value = False
        else:
            try: value = int(value)
            except ValueError: pass
        values[key.strip()] = value
    return {'values': values}
